<script lang="ts" module>
	import type {Snippet} from 'svelte';
	import type {RxColor} from '$lib/registry/lib/color';
	export interface SidebarItem {id:string;label:string;href?:string;icon?:Snippet;badge?:string|number;disabled?:boolean;children?:SidebarItem[]}
	export interface SidebarProps {items:SidebarItem[];active?:string;open?:boolean;collapsed?:boolean;color?:RxColor;variant?:'default'|'classic'|'floating'|'glow'|'gradient'|'minimal'|'rail';side?:'left'|'right';title?:string;collapsible?:boolean;dividers?:boolean;subDots?:boolean;glow?:boolean;scrollbar?:boolean;full?:boolean;flush?:boolean;disabled?:boolean;header?:Snippet;footer?:Snippet;onActiveChange?:(id:string)=>void}
</script>

<script lang="ts">
	import * as SidebarBase from '$lib/components/ui/sidebar/index.js';
	import {styleColor} from '$lib/registry/lib/color';
	import {neighborLight} from '$lib/registry/attachments/neighbor-light';
	import MobileSync from './mobile-sync.svelte';
	let {items,active=$bindable(''),open=$bindable(true),collapsed=$bindable(false),color,variant='default',side='left',title='Navigation',collapsible=true,dividers=false,subDots=true,glow=true,scrollbar=true,full=false,flush=false,disabled=false,header,footer,onActiveChange}:SidebarProps=$props();
	const attachNeighbor=$derived(neighborLight({disabled:()=>disabled||!glow}));
	let expanded=$state<Set<string>>(new Set());
	$effect(()=>{const parent=items.find(item=>item.children?.some(child=>child.id===active));if(parent&&!expanded.has(parent.id))expanded=new Set([...expanded,parent.id])});
	function select(item:SidebarItem,e:MouseEvent){if(disabled||item.disabled){e.preventDefault();return}active=item.id;onActiveChange?.(item.id)}
	function toggleGroup(id:string){const next=new Set(expanded);next.has(id)?next.delete(id):next.add(id);expanded=next}
	function toggleSidebar(){collapsed=!collapsed;open=!collapsed}
	function openChanged(next:boolean){open=next;collapsed=!next}
	function sidebarMotion(node:HTMLElement){
		const foundMenu=node.querySelector<HTMLElement>('[data-rx-sidebar-menu]'),hover=node.querySelector<HTMLElement>('[data-rx-sidebar-hover]'),pill=node.querySelector<HTMLElement>('[data-rx-sidebar-pill]');if(!foundMenu)return;const menu:HTMLElement=foundMenu;
		let frame=0,pointerX=0,pointerY=0;
		function measure(layer:HTMLElement|null,target:HTMLElement|null){if(!layer||!target)return;layer.style.setProperty('--layer-y',`${menu.offsetTop+target.offsetTop}px`);layer.style.setProperty('--layer-h',`${target.offsetHeight}px`);layer.style.setProperty('--layer-x',`${menu.offsetLeft+target.offsetLeft}px`);layer.style.setProperty('--layer-w',`${target.offsetWidth}px`);layer.dataset.ready='true'}
		function activeLayer(){measure(pill,menu.querySelector<HTMLElement>('[data-rx-sidebar-item][data-active="true"]'))}
		function over(e:Event){const target=(e.target as Element|null)?.closest<HTMLElement>('[data-rx-sidebar-item]');if(target)measure(hover,target)}
		function out(e:Event){if(!menu.contains((e as FocusEvent).relatedTarget as Node))hover?.setAttribute('data-ready','false')}
		function paint(){frame=0;const rect=node.getBoundingClientRect(),edgeX=Math.max(rect.left,Math.min(pointerX,rect.right)),edgeY=Math.max(rect.top,Math.min(pointerY,rect.bottom)),intensity=Math.max(0,1-Math.hypot(pointerX-edgeX,pointerY-edgeY)/220);node.style.setProperty('--mx',`${pointerX-rect.left}px`);node.style.setProperty('--my',`${pointerY-rect.top}px`);node.style.setProperty('--glow',intensity.toFixed(3))}
		function move(e:PointerEvent){pointerX=e.clientX;pointerY=e.clientY;if(!frame)frame=requestAnimationFrame(paint)}
		function leave(){node.style.setProperty('--glow','0');hover?.setAttribute('data-ready','false')}
		menu.addEventListener('pointerover',over);menu.addEventListener('focusin',over);menu.addEventListener('pointerleave',leave);menu.addEventListener('focusout',out);node.addEventListener('pointermove',move,{passive:true});node.addEventListener('pointerleave',leave);window.addEventListener('resize',activeLayer,{passive:true});const observer=new MutationObserver(activeLayer);observer.observe(menu,{subtree:true,attributes:true,attributeFilter:['data-active']});requestAnimationFrame(activeLayer);
		return()=>{menu.removeEventListener('pointerover',over);menu.removeEventListener('focusin',over);menu.removeEventListener('pointerleave',leave);menu.removeEventListener('focusout',out);node.removeEventListener('pointermove',move);node.removeEventListener('pointerleave',leave);window.removeEventListener('resize',activeLayer);observer.disconnect();if(frame)cancelAnimationFrame(frame)}
	}
</script>

	<SidebarBase.Provider bind:open onOpenChange={openChanged} style={`${styleColor(color)??'--rx-color:var(--rx-primary)'};--sidebar-width:${variant==='floating'?'88px':variant==='minimal'?'76px':variant==='rail'?'260px':variant==='glow'?'258px':'256px'};--sidebar-width-icon:${variant==='gradient'?'74px':variant==='default'||variant==='classic'?'72px':'76px'}`}>
	<MobileSync {open} onOpenChange={openChanged}/>
	<SidebarBase.Root {side} variant={variant==='floating'?'floating':'sidebar'} collapsible={collapsible?'icon':'none'} class="rx-sidebar rx-sidebar--{variant} {collapsed?'is-collapsed':''}">
		<div class="rx-sidebar__surface rx-sidebar--{variant} {collapsed?'is-collapsed':''} {full?'is-full':''} {flush?'is-flush':''} {scrollbar?'':'no-scroll'} {glow?'':'no-glow'} {disabled?'is-disabled':''}" aria-disabled={disabled?'true':undefined} {@attach sidebarMotion} {@attach attachNeighbor}><span class="rx-sidebar__grain" aria-hidden="true"></span><span class="rx-sidebar__proximity" aria-hidden="true"></span>
			<SidebarBase.Header class="rx-sidebar__header"><div class="rx-sidebar__brand">{#if header}{@render header()}{:else}<strong>{title}</strong>{/if}</div>{#if collapsible}<button class="rx-sidebar__collapse" type="button" disabled={disabled} aria-label={collapsed?'Expand sidebar':'Collapse sidebar'} aria-expanded={!collapsed} onclick={toggleSidebar}><span aria-hidden="true">‹</span></button>{/if}</SidebarBase.Header>
			<SidebarBase.Content class="rx-sidebar__content"><nav aria-label="Sidebar navigation"><span class="rx-sidebar__hover" data-rx-sidebar-hover data-ready="false" aria-hidden="true"></span><span class="rx-sidebar__pill" data-rx-sidebar-pill data-ready="false" aria-hidden="true"></span><ul class="rx-sidebar__menu" data-rx-sidebar-menu>
				{#each items as item,i(item.id)}{#if dividers&&i>0}<li class="rx-sidebar__divider" aria-hidden="true"></li>{/if}<li class="rx-sidebar__group" data-tip={item.children?.length?undefined:item.label}><div class="rx-sidebar__row"><a data-rx-sidebar-item data-active={active===item.id?'true':'false'} class="rx-sidebar__item" class:is-active={active===item.id} class:is-child-active={Boolean(item.children?.some(child=>child.id===active))} href={item.href??'#'} title={item.label} aria-current={active===item.id?'page':undefined} aria-disabled={disabled||item.disabled?'true':undefined} tabindex={disabled||item.disabled?-1:undefined} onclick={(e)=>select(item,e)}><span class="rx-sidebar__scan" aria-hidden="true"></span><span class="rx-sidebar__active-mark" aria-hidden="true">›</span><span class="rx-sidebar__ring" aria-hidden="true"></span>{#if item.icon}<span class="rx-sidebar__icon" aria-hidden="true">{@render item.icon()}</span>{/if}<span class="rx-sidebar__label">{item.label}</span>{#if item.badge!==undefined}<span class="rx-sidebar__badge">{item.badge}</span>{/if}</a>{#if item.children?.length}<button class="rx-sidebar__chevron" class:is-open={expanded.has(item.id)} type="button" disabled={disabled} aria-label={`${expanded.has(item.id)?'Collapse':'Expand'} ${item.label}`} aria-expanded={expanded.has(item.id)} onclick={()=>toggleGroup(item.id)}><span aria-hidden="true">⌄</span></button>{/if}</div>
					{#if item.children?.length}<div class="rx-sidebar__sub" class:is-open={expanded.has(item.id)}><div class="rx-sidebar__subclip">{#each item.children as child(child.id)}<a class="rx-sidebar__subitem" class:is-active={active===child.id} href={child.href??'#'} aria-current={active===child.id?'page':undefined} aria-disabled={disabled||child.disabled?'true':undefined} tabindex={disabled||child.disabled?-1:undefined} onclick={(e)=>select(child,e)}>{#if subDots}<i aria-hidden="true"></i>{/if}{child.label}</a>{/each}</div></div><div class="rx-sidebar__fly"><strong>{item.label}</strong>{#each item.children as child(child.id)}<a class:is-active={active===child.id} href={child.href??'#'} aria-disabled={disabled||child.disabled?'true':undefined} tabindex={disabled||child.disabled?-1:undefined} onclick={(e)=>select(child,e)}>{#if subDots}<i aria-hidden="true"></i>{/if}{child.label}</a>{/each}</div>{/if}
				</li>{/each}
			</ul></nav></SidebarBase.Content>
			{#if footer}<SidebarBase.Footer class="rx-sidebar__footer">{@render footer()}</SidebarBase.Footer>{/if}
		</div>
	</SidebarBase.Root>
</SidebarBase.Provider>

<style>
	:global(.rx-sidebar__content) nav{position:relative}
	:global(.rx-sidebar){--sidebar:rgb(var(--rx-bg));--sidebar-foreground:rgb(var(--rx-text));--sidebar-border:rgb(var(--rx-text)/.09);--sidebar-ring:rgb(var(--rx-color)/.45)}:global(.rx-sidebar [data-slot=sidebar-gap]),:global(.rx-sidebar [data-slot=sidebar-container]){transition-duration:460ms;transition-timing-function:cubic-bezier(.34,1.4,.6,1)}:global(.rx-sidebar [data-slot=sidebar-inner]){overflow:visible;background:transparent;box-shadow:none}.rx-sidebar__surface{position:relative;isolation:isolate;display:flex;flex-direction:column;width:100%;height:100%;padding:14px 12px;gap:4px;border:1px solid rgb(var(--rx-text)/.09);border-radius:20px;background:rgb(var(--rx-bg)/.92);color:rgb(var(--rx-text));overflow:hidden;transition:width 460ms cubic-bezier(.34,1.4,.6,1)}.rx-sidebar__surface>*:not(.rx-sidebar__grain,.rx-sidebar__proximity){position:relative;z-index:2}.rx-sidebar__proximity{position:absolute;inset:-1px;z-index:3;border-radius:inherit;padding:1px;pointer-events:none;background:radial-gradient(60px circle at var(--mx,50%) var(--my,50%),rgb(var(--rx-color)/.62),rgb(var(--rx-color)/.25) 50%,transparent 82%);mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude;opacity:calc(var(--glow,0)*.7);transition:opacity 140ms}:global(.rx-sidebar__header){display:flex;align-items:center;gap:10px;min-height:40px}.rx-sidebar__brand{flex:1;white-space:nowrap;overflow:hidden}.rx-sidebar__collapse{display:grid;place-items:center;flex:none;width:30px;height:30px;border:0;border-radius:9px;color:inherit;background:transparent;cursor:pointer;transition:background 160ms,transform 480ms cubic-bezier(.34,1.56,.64,1)}.rx-sidebar__collapse:hover{background:rgb(var(--rx-color)/.1)}.rx-sidebar__collapse:focus-visible{outline:2px solid rgb(var(--rx-color))}.is-collapsed .rx-sidebar__collapse{transform:rotate(180deg)}.is-collapsed .rx-sidebar__brand{display:none}:global(.rx-sidebar__content){overflow:visible!important}.rx-sidebar__menu{position:relat