und:rgb(var(--rx-color));box-shadow:0 6px 16px -6px rgb(var(--rx-color)/.45);transition-duration:620ms;transition-timing-function:linear(0,.02,.08,.18,.32,.48,.64,.78,.89,.965,1.012,1.038,1.048,1.045,1.034,1.02,1.007,.998,.994,.996,.999,1)}.rx-sidebar--rail .rx-sidebar__pill:global([data-ready=true]){opacity:1}.rx-sidebar--rail .rx-sidebar__item.is-active{color:var(--rx-color-foreground,rgb(var(--rx-bg)))}.rx-sidebar__sub{display:grid;grid-template-rows:0fr;transition:grid-template-rows 500ms cubic-bezier(.5,-.6,.5,1)}.rx-sidebar__sub.is-open{grid-template-rows:1fr;transition-duration:560ms;transition-timing-function:cubic-bezier(.34,1.8,.5,1)}.rx-sidebar__subclip{display:flex;flex-direction:column;gap:2px;padding-left:22px;overflow:hidden;opacity:0;transform:translateY(-6px) scale(.97);filter:blur(8px);transition:opacity 260ms,transform 500ms,filter 400ms}.rx-sidebar__sub.is-open .rx-sidebar__subclip{padding-top:3px;opacity:1;transform:none;filter:none}.rx-sidebar__subitem{display:flex;align-items:center;gap:9px;height:33px;padding:0 12px;border-radius:9px;color:rgb(var(--rx-text)/.55);font-size:13px;text-decoration:none}.rx-sidebar__subitem:hover,.rx-sidebar__subitem.is-active{color:rgb(var(--rx-color));background:rgb(var(--rx-color)/.07)}.rx-sidebar__subitem i,.rx-sidebar__fly i{width:5px;height:5px;border-radius:50%;background:currentColor;opacity:.5}.rx-sidebar__fly{display:none}.rx-sidebar__ring,.rx-sidebar__scan,.rx-sidebar__active-mark{display:none}
	.rx-sidebar__surface.rx-sidebar--classic{border-radius:0;border-block:0;border-inline-start:0}.rx-sidebar__surface.rx-sidebar--floating{align-items:center;width:66px;padding:12px 10px;border-radius:24px;background:rgb(var(--rx-bg)/.85);backdrop-filter:blur(16px);box-shadow:0 26px 64px -22px rgb(var(--rx-dark)/.6),0 2px 8px rgb(var(--rx-dark)/.3)}.rx-sidebar--floating :global(.rx-sidebar__header),.rx-sidebar--minimal :global(.rx-sidebar__header),.rx-sidebar--floating :global(.rx-sidebar__footer),.rx-sidebar--minimal :global(.rx-sidebar__footer){display:none}.rx-sidebar--floating .rx-sidebar__menu,.rx-sidebar--minimal .rx-sidebar__menu{align-items:center;gap:8px}.rx-sidebar--floating .rx-sidebar__item,.rx-sidebar--minimal .rx-sidebar__item{justify-content:center;width:46px;height:46px;padding:0}.rx-sidebar--floating .rx-sidebar__item{border-radius:15px;background:rgb(var(--rx-color)/.05)}.rx-sidebar--floating .rx-sidebar__item:hover:not(.is-active){transform:scale(1.14);background:rgb(var(--rx-color)/.1)}.rx-sidebar--floating .rx-sidebar__item.is-active{color:var(--rx-color-foreground,rgb(var(--rx-bg)));background:rgb(var(--rx-color));transform:scale(1.06);box-shadow:0 10px 22px -8px rgb(var(--rx-color)/.55)}.rx-sidebar--floating .rx-sidebar__item.is-active::before{content:'';position:absolute;left:-11px;top:50%;width:4px;height:20px;translate:0 -50%;border-radius:999px;background:rgb(var(--rx-color))}.rx-sidebar--floating .rx-sidebar__label,.rx-sidebar--minimal .rx-sidebar__label{display:none}.rx-sidebar--floating .rx-sidebar__badge,.rx-sidebar--minimal .rx-sidebar__badge{position:absolute;top:-3px;right:-3px;min-width:17px;height:17px;font-size:10px}.rx-sidebar--floating .rx-sidebar__chevron,.rx-sidebar--minimal .rx-sidebar__chevron,.rx-sidebar--floating .rx-sidebar__sub,.rx-sidebar--minimal .rx-sidebar__sub{display:none}.rx-sidebar--floating .rx-sidebar__group[data-tip]::after,.rx-sidebar--minimal .rx-sidebar__group[data-tip]::after,.rx-sidebar--floating .rx-sidebar__fly,.rx-sidebar--minimal .rx-sidebar__fly{content:attr(data-tip);position:absolute;left:calc(100% + 14px);top:50%;z-index:20;display:block;padding:6px 10px;border:1px solid rgb(var(--rx-text)/.09);border-radius:9px;color:rgb(var(--rx-text));background:rgb(var(--rx-bg));box-shadow:0 16px 40px -12px rgb(var(--rx-dark)/.55);font-size:12.5px;white-space:nowrap;opacity:0;pointer-events:none;transform:translateY(-50%) translateX(-6px) scale(.96);transform-origin:left center;transition:opacity 160ms,transform 260ms cubic-bezier(.34,1.7,.5,1)}.rx-sidebar--floating .rx-sidebar__fly,.rx-sidebar--minimal .rx-sidebar__fly{top:0;display:flex;flex-direction:column;gap:1px;min-width:180px;transform:translateX(-6px) scale(.96)}.rx-sidebar__fly strong{margin:2px 8px 5px;color:rgb(var(--rx-text)/.5);font-size:10.5px;text-transform:uppercase}.rx-sidebar__fly a{display:flex;align-items:center;gap:9px;height:34px;padding:0 10px;border-radius:9px;color:rgb(var(--rx-text)/.64);text-decoration:none}.rx-sidebar__fly a:hover,.rx-sidebar__fly a.is-active{color:rgb(var(--rx-text));background:rgb(var(--rx-color)/.07)}.rx-sidebar__group[data-tip]:is(:hover,:focus-within)::after,.rx-sidebar__group:is(:hover,:focus-within)>.rx-sidebar__fly{opacity:1;pointer-events:auto;transform:translateY(-50%) translateX(0) scale(1)}.rx-sidebar__group:is(:hover,:focus-within)>.rx-sidebar__fly{transform:translateX(0) scale(1)}
	.rx-sidebar__surface.rx-sidebar--minimal{align-items:center;width:60px;padding:14px 8px;border:0;border-radius:0;background:transparent}.rx-sidebar--minimal .rx-sidebar__item{width:44px;height:44px;color:rgb(var(--rx-text)/.58)}.rx-sidebar--minimal .rx-sidebar__ring{position:absolute;inset:4px;z-index:0;display:block;border-radius:999px;background:rgb(var(--rx-color));opacity:0;transform:scale(.2);transition:transform 360ms cubic-bezier(.34,1.56,.64,1),opacity 200ms}.rx-sidebar--minimal .rx-sidebar__item.is-active{color:var(--rx-color-foreground,rgb(var(--rx-bg)))}.rx-sidebar--minimal .rx-sidebar__item.is-active .rx-sidebar__ring{opacity:1;transform:scale(1)}.rx-sidebar--minimal .rx-sidebar__item:hover:not(.is-active) .rx-sidebar__ring{opacity:.08;transform:scale(1)}
	.rx-sidebar__surface.rx-sidebar--glow{border-radius:8px;border-color:rgb(var(--rx-color)/.22);background:linear-gradient(180deg,rgb(var(--rx-color)/.05),transparent 40%),rgb(var(--rx-bg));font-family:ui-monospace,'SF Mono',monospace}.rx-sidebar--glow .rx-sidebar__item{height:40px;border-left:2px solid transparent;border-radius:0 6px 6px 0;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase}.rx-sidebar--glow .rx-sidebar__item.is-active{color:rgb(var(--rx-color));border-left-color:rgb(var(--rx-color));background:linear-gradient(90deg,rgb(var(--rx-color)/.14),transparent 75%);text-shadow:0 0 10px rgb(var(--rx-color)/.55)}.rx-sidebar--glow .rx-sidebar__scan{position:absolute;inset:0;display:block;overflow:hidden;opacity:0}.rx-sidebar--glow .rx-sidebar__item.is-active .rx-sidebar__scan{opacity:1}.rx-sidebar--glow .rx-sidebar__scan::after{content:'';position:absolute;left:0;right:0;height:40%;background:linear-gradient(180deg,transparent,rgb(var(--rx-color)/.12),transparent);animation:rx-sidebar-scan 2.6s linear infinite}.rx-sidebar--glow .rx-sidebar__active-mark{display:block;color:rgb(var(--rx-color));opacity:0;transform:translateX(-4px);transition:opacity 180ms,transform 220ms}.rx-sidebar--glow .rx-sidebar__item.is-active .rx-sidebar__active-mark{opacity:1;transform:none}@keyframes rx-sidebar-scan{from{top:-40%}to{top:100%}}
	.rx-sidebar__surface.rx-sidebar--gradient{border:0;background:linear-gradient(160deg,rgb(var(--rx-color)),hsl(from rgb(var(--rx-color)) calc(h + 55) s calc(l*.28)) 120%);background-size:100% 160%;color:rgb(var(--rx-light));box-shadow:0 24px 60px -22px rgb(var(--rx-color)/.55);animation:rx-sidebar-drift 12s ease-in-out infinite}.rx-sidebar--gradient .rx-sidebar__grain{position:absolute;inset:0;display:block;background:radial-gradient(120% 60% at 100% 0%,rgb(var(--rx-light)/.18),transparent 60%),radial-gradient(80% 50% at 0 100%,rgb(var(--rx-dark)/.18),transparent 60%)}.rx-sidebar--gradient .rx-sidebar__item{color:rgb(var(--rx-light)/.82)}.rx-sidebar--gradient .rx-sidebar__item:hover{color:rgb(var(--rx-light));background:rgb(var(--rx-light)/.12)}.rx-sidebar--gradient .rx-sidebar__item.is-active{color:rgb(var(--rx-color));background:rgb(var(--rx-light)/.96);box-shadow:0 8px 20px -8px rgb(var(--rx-dark)/.35)}.rx-sidebar--gradient .rx-sidebar__badge{color:rgb(var(--rx-light));background:rgb(var(--rx-light)/.22)}@keyframes rx-sidebar-drift{50%{background-position:0 100%}}
